import re
from collections import Counter

counts = Counter()
with open("auth.log", encoding="utf-8") as f:
    for line in f:
        m = re.search(r"Failed password for (\S+) from (\S+)", line)
        if m:
            counts[m.group(2)] += 1
for ip in sorted(counts, key=lambda k: (-counts[k], k)):
    print(ip + ": " + str(counts[ip]))

import re
from collections import Counter

counts = Counter()
with open("auth.log", encoding="utf-8") as f:
    for line in f:
        m = re.search(r"Failed password for (\S+) from (\S+)", line)
        if m:
            counts[m.group(2)] += 1
bad = sorted(ip for ip in counts if counts[ip] >= 3)
if bad:
    for ip in bad:
        print("ALERT " + ip)
else:
    print("no alerts")

import re

users = {}
with open("auth.log", encoding="utf-8") as f:
    for line in f:
        m = re.search(r"Failed password for (\S+) from (\S+)", line)
        if m:
            users.setdefault(m.group(2), set()).add(m.group(1))
for ip in sorted(users):
    print(ip + ": " + str(len(users[ip])))

def burst(times, limit, window):
    for i in range(len(times) - limit + 1):
        if times[i + limit - 1] - times[i] <= window:
            return True
    return False
